fields.InputDefinition:
{
  "goal": "In Component Studio → Form Studio, click the '+ New' button above the Forms rail to start a new form. In the center toolbar, click the entity picker button ('Pick entity…') to open its popover, type into its 'Search entities…' box, and select an entity from the filtered list. Verify the picker closes and the chosen entity name shows in the toolbar, and the center pane transitions from the 'Pick an entity to start' prompt toward the editor. You may also set a form name in the 'Form name…' input. Pages can take 10-30s to load — wait, don't navigate away. Seeing the entity picker filter and bind an entity is success — you do NOT need to save the form.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Clicking '+ New' begins a new form and the center shows an entity picker prompt",
    "Opening the entity picker, searching, and selecting an entity binds that entity (its name appears in the toolbar and the empty 'pick an entity' prompt clears)",
    "No error messages, blank screens, or crash pages"
  ]
}
